arguments.command:
curl -s -X POST https://slack.com/api/users.list -H "Authorization: Bearer <TOKEN>" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERROR:', d); sys.exit(1)
for u in d['members']:
    name=u.get('profile',{}).get('real_name','')
    if 'john' in name.lower():
        print(u['id'], '|', name, '|', u.get('profile',{}).get('display_name',''), '|', 'deleted' if u.get('deleted') else 'active')
"

